const item = $input.first();
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
if (Buffer.byteLength(raw, 'utf8') > 16384) throw new Error('Outcome too large');
const timestamp = item.json.headers['x-threshold-timestamp'];
if (!/^[0-9]+$/.test(timestamp || '') || Math.abs(Date.now()/1000 - Number(timestamp)) > 300) throw new Error('Expired outcome');
return [{json:{payload:JSON.parse(raw), signed_text:timestamp + '.' + raw,
 supplied_signature:item.json.headers['x-threshold-signature'],
 header_delivery_id:item.json.headers['x-threshold-delivery-id']}}];

// Configure for ONE Threshold organization and ONE HubSpot account.
const config = {
  organization_id: '9a6f3a10-8d33-42a1-9586-cebb8e65d5e4',
  portal_id: '247531757',
  completed_stage_id: '4',
  cancelled_stage_id: '4'
};
const p = $json.payload;
const supplied = String($json.supplied_signature || '').replace(/^sha256=/,'');
const expected = String($json.expected_signature || '');
if (!/^[a-f0-9]{64}$/.test(supplied) || !/^[a-f0-9]{64}$/.test(expected)) throw new Error('Invalid signature');
let diff = 0;
for (let i=0; i<64; i++) diff |= supplied.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Invalid signature');
if (!p || p.schema_version !== 1 || p.type !== 'threshold.refund.final') throw new Error('Unsupported outcome');
if (p.organization_id !== config.organization_id || p.crm?.portal_id !== config.portal_id || p.crm?.provider !== 'hubspot') throw new Error('Organization or CRM account mismatch');
if (!/^[0-9]{1,32}$/.test(p.crm.ticket_id || '')) throw new Error('Invalid ticket ID');
if (!['completed','cancelled'].includes(p.status) || (p.status === 'completed' && p.verified !== true)) throw new Error('Outcome not final or verified');
if (typeof p.delivery_id !== 'string' || p.delivery_id !== $json.header_delivery_id) throw new Error('Delivery ID mismatch');
const stage = p.status === 'completed' ? config.completed_stage_id : config.cancelled_stage_id;
if (!/^[0-9]+$/.test(stage)) throw new Error('Configure the HubSpot internal stage IDs');
return [{json:{delivery_id:p.delivery_id, ticket_id:p.crm.ticket_id,
 properties:{hs_pipeline_stage:stage}}}];

const expected = $('Validate and Map Outcome').first().json;
const status = Number($json.statusCode);
const good = status === 200 && String($json.body?.id) === expected.ticket_id;
// Never acknowledge an update to the wrong record or a generic green execution.
return [{json:{response_code:good ? 200 : (status === 200 ? 502 : status),
 retry_after:String($json.headers?.['retry-after'] || '0'),
 response:good ? {ok:true, delivery_id:expected.delivery_id} : {ok:false, code:'CRM_SYNC_FAILED'}}}];
